import type {
    API,
    ASTNode,
    FileInfo,
    ObjectProperty,
    Property,
} from "jscodeshift"
import { getStringValue } from "../ast-helpers"

export const name = path.basename(__filename, path.extname(__filename))
export const description =
    'remove redundant `driver: require("expo-sqlite")` from Expo DataSource options'

// Returns true when `node` is exactly a call expression `require("expo-sqlite")`
// — a plain, direct require call. Member accesses (`require("expo-sqlite").default`),
// identifiers/variables, and requires of other packages are intentionally
// rejected so the transform only strips the value TypeORM now auto-loads.
const isExpoSqliteRequire = (node: ASTNode): boolean => {
    if (node.type !== "CallExpression") return false
    if (
        node.callee.type !== "Identifier" ||
        node.callee.name !== "require"
    ) {
        return false
    }
    const [arg] = node.arguments
    return arg !== undefined && getStringValue(arg) === "expo-sqlite"
}

export const datasourceExpo = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    let hasChanges = false

    // Scope to ObjectExpressions that look like Expo DataSource options —
    // they must carry both `type: "expo"` and a sibling `database` property.
    // Requiring `database` avoids false positives on unrelated `{ type: "expo" }`
    // objects. Accept both `Property` (Esprima) and `ObjectProperty` (Babel),
    // and both identifier (`type:`) and string-literal (`"type":`) keys.
    root.find(j.ObjectExpression).forEach((objPath) => {
        let isExpo = false
        let hasDatabase = false
        let driverProp: ObjectProperty | Property | null = null

        for (const prop of objPath.node.properties) {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                continue
            }

            const keyName =
                prop.key.type === "Identifier"
                    ? prop.key.name
                    : getStringValue(prop.key)

            if (keyName === "type" && getStringValue(prop.value) === "expo") {
                isExpo = true
            } else if (keyName === "database") {
                hasDatabase = true
            } else if (keyName === "driver") {
                driverProp = prop
            }
        }

        if (!isExpo || !hasDatabase || !driverProp) return
        if (!isExpoSqliteRequire(driverProp.value)) return

        objPath.node.properties = objPath.node.properties.filter(
            (prop) => prop !== driverProp,
        )
        hasChanges = true
    })

    return hasChanges ? root.toSource() : undefined
}

export const fn = datasourceExpo
export default fn
